SELECT inquiries_file_id, inquiry_id, original_name, stored_name, file_path, file_size, uploaded
FROM inquiries_file
WHERE inquiries_file_id = #{inquiries_file_id}

SELECT inquiry_id, member_id, title, content, status, answer_content, answered, created, updated
FROM inquiries
